describe('Payment Flow - Select PayPal as Payment Method', () => {
    beforeEach(() => {
        cy.visit('/checkout'); // Adjust the URL to your checkout page
    });

    it('should successfully select PayPal as the payment method', () => {
        cy.get('select[name="paymentMethod"]').select('PayPal');
        cy.get('button[type="submit"]').click();
        cy.url().should('include', '/payment-confirmation'); // Adjust the URL to your payment confirmation page
        cy.contains('Payment Method: PayPal').should('be.visible');
    });

    it('should show an error when PayPal is not available', () => {
        cy.intercept('GET', '/api/payment-methods', {
            statusCode: 200,
            body: { methods: [] } // Simulate no payment methods available
        }).as('getPaymentMethods');

        cy.reload();
        cy.wait('@getPaymentMethods');

        cy.get('select[name="paymentMethod"]').should('not.exist');
        cy.contains('No payment methods available').should('be.visible');
    });
});
